INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('standard_dilution_reference', 'assay_import', 'Standard curve dilution reference (label -> dilution, JSON)', 'character', 'textInput', NULL, NULL, 'Usually set automatically during import (Standards dilution reference step); edit here directly only to add or correct a value for the whole study without re-importing.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('failed_well_criteria', 'bead_count', 'Failed Well Criteria', 'character', 'radioButtons', 'Below_Upper_Threshold,Below_Lower_Threshold', 35, 'Rule that marks a well failed (below upper vs. below lower threshold).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('lower_bc_threshold', 'bead_count', 'Lower Threshold', 'numeric', 'numericInput', 'NA,Inf', 9, 'Minimum bead count for a well to be usable.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('pct_agg_threshold', 'bead_count', 'Aggregate Beads Threshold', 'numeric', 'numericInput', 'NA,Inf', 9, 'Maximum percent aggregate beads before a well is flagged.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('upper_bc_threshold', 'bead_count', 'Upper Threshold', 'numeric', 'numericInput', 'NA,Inf', 9, 'Bead count above which a well is flagged.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('adapt_delta', 'calibration', 'Bayesian sampler target acceptance (adapt_delta)', 'numeric', 'numericInput', NULL, NULL, 'Bayesian only: NUTS target acceptance (0-1). Raise toward 0.95-0.99 if a fit reports divergences.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('apply_prozone', 'calibration', 'Apply prozone correction', 'boolean', 'switchInput', 'TRUE,FALSE', NULL, 'Apply the high-dose hook (prozone) correction when a curve hooks at high concentration.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('bayes_chains', 'calibration', 'Bayesian chains', 'integer', 'numericInput', NULL, NULL, 'Bayesian only: number of MCMC chains.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('bayes_sampling', 'calibration', 'Bayesian post-warmup draws/chain', 'integer', 'numericInput', NULL, NULL, 'Bayesian only: post-warmup draws per chain. Higher = smoother posteriors, slower fits.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('bayes_single_plate', 'calibration', 'Bayesian single-plate (unpooled) fit', 'boolean', 'switchInput', NULL, NULL, 'Bayesian only. If TRUE, each plate is fit independently (N_plates = 1, no cross-plate pooling) instead of one multiplate hierarchy. Default FALSE (multiplate pooling). The frequentist engine is always per-plate and ignores this flag.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('bayes_warmup', 'calibration', 'Bayesian warmup iterations', 'integer', 'numericInput', NULL, NULL, 'Bayesian only: warmup (burn-in) iterations per chain.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('blank_option', 'calibration', 'Blank control handling', 'character', 'radioButtons', 'ignored,included,subtracted,subtracted_3x,subtracted_10x', NULL, 'How blank/background wells are handled (ignored, included, or subtracted at a multiple).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('decision_cutoff', 'calibration', 'Decision cutoff (concentration)', 'numeric', 'numericInput', NULL, NULL, 'Optional concentration threshold, in the same dilution-corrected units as final_concentration (e.g. a protective level). Each sample then gets p_below_cutoff, the probability its concentration is below it. Leave unset for none. Usually set per antigen.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('include_measurement_error', 'calibration', 'Include assay measurement error', 'boolean', 'switchInput', 'TRUE,FALSE', NULL, 'Bayesian only: propagate assay measurement error into the posterior (false = curve-only precision).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('is_log_independent', 'calibration', 'Log-transform concentration axis', 'boolean', 'switchInput', 'TRUE,FALSE', NULL, 'Fit on a log-transformed concentration axis.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('is_log_response', 'calibration', 'Log-transform response axis', 'boolean', 'switchInput', 'TRUE,FALSE', NULL, 'Fit on a log-transformed response (MFI) axis.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('l_asy_constraint_method', 'calibration', 'Lower-asymptote constraint method', 'character', 'radioButtons', 'default', NULL, 'Lower-asymptote constraint method (legacy).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('l_asy_max_constraint', 'calibration', 'Lower-asymptote max constraint', 'numeric', 'numericInput', NULL, NULL, 'Lower-asymptote upper bound (legacy; active only under a non-default constraint method).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('l_asy_min_constraint', 'calibration', 'Lower-asymptote min constraint', 'numeric', 'numericInput', NULL, NULL, 'Lower-asymptote lower bound (legacy; active only under a non-default constraint method).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('model_form_list', 'calibration', 'Models to fit', 'character', 'selectInput,multiple', 'logistic4,loglogistic4,gompertz4,logistic5,loglogistic5', NULL, 'Which curve models are fit and compared (each scored independently; order is cosmetic).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('n_interval_draws', 'calibration', 'Interval draws (frequentist)', 'integer', 'numericInput', NULL, NULL, 'Monte Carlo draws per sample for frequentist predictive intervals and threshold probabilities. Default 1000; 0 disables them. Bayesian fits use their posterior draws instead.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('noise_model', 'calibration', 'Response noise model', 'character', 'radioButtons', 'constant,add_prop', NULL, 'How the spread of the standards around the curve is modelled. constant (default): one SD on the fitting scale. add_prop: an additive floor plus a part proportional to the response, sqrt(sigma_add^2 + (cv * mean)^2), estimated once per fit group. Use add_prop for absorbance (ELISA OD), where a constant SD over-trusts either the low end (log response) or the high end (linear response).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('pcov_threshold', 'calibration', 'Precision budget (%CV)', 'numeric', 'numericInput', NULL, NULL, 'Replicate precision gate, as a %CV. Standard-curve points whose replicate %CV exceeds this value are excluded from the fit. The settings migration reset every study to a single global default of 20. Raising it admits noisier standards (more points kept, looser fit); lowering it is stricter (fewer points kept). Change this only for a specific study/experiment/feature/antigen where the default gate is demonstrably wrong for that assay.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('persist_draws', 'calibration', 'Persist posterior/sampling draws', 'boolean', 'switchInput', NULL, NULL, 'If TRUE, the fitting engine writes the full posterior (Bayesian) or asymptotic-MVN (frequentist) parameter draws to calib_draws. Heavy output; default FALSE. Does not gate calib_hyperparam / calib_fit_diag.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('standard_curve_concentration', 'calibration', 'Top standard concentration', 'numeric', 'numericInput', NULL, NULL, 'Top standard concentration for this antigen, in the reported unit. Antigen-intrinsic; set per antigen.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('is_binary_gc', 'dilution_analysis', 'Use Passing Limit of Detection as binary', 'boolean', 'checkbox', 'TRUE,FALSE', 9, 'Treat the passing limit-of-detection gate as a binary pass/fail.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('node_order', 'dilution_analysis', 'Type of Sample Limit', 'character', 'selectInput, multiple', 'limits_of_detection,limits_of_quantification,linear_region', 20, 'Which limit type bounds a sample (limits of detection vs. limits of quantification).') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('one_pass_acceptable_Tx', 'dilution_analysis', 'One Passing Dilution AU Treatment:', 'character', 'radioButtons', 'all_au,passing_au,geom_all_au,geom_passing_au,replace_blank,exclude_au', 20, 'AU treatment when exactly one dilution passes.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('two_plus_pass_acceptable_Tx', 'dilution_analysis', 'Two or More Passing Dilution AU Treatment:', 'character', 'radioButtons', 'all_au,passing_au,geom_all_au,geom_passing_au,replace_blank,exclude_au', 20, 'AU treatment when two or more dilutions pass.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('valid_gate_class', 'dilution_analysis', 'Passing Limit of Detection', 'character', 'selectInput', 'Between_Limits_of_Detection,Above_Upper_Limit_of_Detection,Below_Lower_Limit_of_Detection', 20, 'Which gate classification counts as a passing/valid measurement.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('zero_pass_concentrated_diluted_Tx', 'dilution_analysis', 'Zero Passing Dilutions Too Concentrated and Too Diluted AU Treatment:', 'character', 'radioButtons', 'all_au,passing_au,geom_all_au,geom_passing_au,replace_blank,exclude_au', 20, 'AU treatment when zero dilutions pass and the sample is both too concentrated and too diluted.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('zero_pass_concentrated_Tx', 'dilution_analysis', 'Zero Passing Dilutions Too Concentrated AU Treatment:', 'character', 'radioButtons', 'all_au,passing_au,geom_all_au,geom_passing_au,replace_blank,exclude_au', 20, 'AU treatment when zero dilutions pass and the sample is too concentrated.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('zero_pass_diluted_Tx', 'dilution_analysis', 'Zero Passing Dilutions Too Diluted AU Treatment:', 'character', 'radioButtons', 'all_au,passing_au,geom_all_au,geom_passing_au,replace_blank,exclude_au', 20, 'AU treatment when zero dilutions pass and the sample is too diluted.') ON CONFLICT (param_name) DO NOTHING;
INSERT INTO madi_results.calib_settings_meta (param_name, param_group, param_label, param_data_type, param_control_type, param_choices_list, param_char_len, param_description) VALUES ('compute_cluster', 'infrastructure', 'Compute cluster (i-spi-compute clone routing label)', 'character', 'textInput', NULL, NULL, 'Which deployed i-spi-compute clone this project/study submits fit jobs to. Leave unset to use the default clone. Must match a clone label the app is configured with (ISPI_COMPUTE_URL__<LABEL> env var on the app pod) -- an unrecognized label silently falls back to the default clone.') ON CONFLICT (param_name) DO NOTHING;
